@contextmanager
def _temporary_random_seed(seed: int):
    """Seed Python's and NumPy's global RNGs, then restore both (SW-589 L3).

    The validation drawers use ``random`` and the shipped models set their own
    ``random_state``, so seeding NumPy changes no current result. It keeps a
    run reproducible if any code in the block draws from ``np.random``.
    """
    state = random.getstate()
    np_state = np.random.get_state()
    random.seed(seed)
    np.random.seed(seed)
    try:
        yield
    finally:
        random.setstate(state)
        np.random.set_state(np_state)


